"use strict";(globalThis.webpackChunkphysical_ai_humanoid_robotics=globalThis.webpackChunkphysical_ai_humanoid_robotics||[]).push([[5894],{6042:e=>{e.exports=JSON.parse('{"blogPosts":[{"id":"introduction-to-physical-ai","metadata":{"permalink":"/blog/introduction-to-physical-ai","editUrl":"https://github.com/panaversity/physical-ai-humanoid-robotics/tree/main/blog/introduction-to-physical-ai.md","source":"@site/blog/introduction-to-physical-ai.md","title":"Introduction to Physical AI","description":"Physical AI represents a paradigm shift from digital intelligence to embodied intelligence. Unlike traditional AI that operates in virtual spaces, Physical AI systems function in the real world, understanding and manipulating physical objects and environments.","date":"2025-12-06T21:29:37.000Z","formattedDate":"December 6, 2025","tags":[{"label":"physical-ai","permalink":"/blog/tags/physical-ai"},{"label":"robotics","permalink":"/blog/tags/robotics"},{"label":"embodied-intelligence","permalink":"/blog/tags/embodied-intelligence"}],"readingTime":0.605,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"introduction-to-physical-ai","title":"Introduction to Physical AI","tags":["physical-ai","robotics","embodied-intelligence"]},"nextItem":{"title":"ROS 2 Fundamentals Explained","permalink":"/blog/ros2-fundamentals"}},"content":"Physical AI represents a paradigm shift from digital intelligence to embodied intelligence. Unlike traditional AI that operates in virtual spaces, Physical AI systems function in the real world, understanding and manipulating physical objects and environments.\\n\\n## What is Embodied Intelligence?\\n\\nEmbodied intelligence refers to AI systems that interact with the physical world through sensors and actuators. These systems must understand physical laws, spatial relationships, and material properties to function effectively.\\n\\n## The Robotics Stack\\n\\nModern robotics requires integration across multiple layers:\\n\\n- **Perception**: Understanding the environment through sensors\\n- **Planning**: Deciding what actions to take\\n- **Control**: Executing precise motor commands\\n- **Learning**: Adapting to new situations and improving over time\\n\\nStay tuned for deeper dives into each of these components!"},{"id":"ros2-fundamentals","metadata":{"permalink":"/blog/ros2-fundamentals","editUrl":"https://github.com/panaversity/physical-ai-humanoid-robotics/tree/main/blog/ros2-fundamentals.md","source":"@site/blog/ros2-fundamentals.md","title":"ROS 2 Fundamentals Explained","description":"Robot Operating System 2 (ROS 2) is the next generation of the Robot Operating System, designed for production environments. It provides a flexible framework for writing robot software and is widely used in both academic and industrial robotics applications.","date":"2025-12-06T21:29:37.000Z","formattedDate":"December 6, 2025","tags":[{"label":"ros2","permalink":"/blog/tags/ros-2"},{"label":"robotics","permalink":"/blog/tags/robotics"},{"label":"fundamentals","permalink":"/blog/tags/fundamentals"}],"readingTime":0.96,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"ros2-fundamentals","title":"ROS 2 Fundamentals Explained","tags":["ros2","robotics","fundamentals"]},"prevItem":{"title":"Introduction to Physical AI","permalink":"/blog/introduction-to-physical-ai"},"nextItem":{"title":"Welcome to Our Robotics Blog","permalink":"/blog/welcome-to-blog"}},"content":"Robot Operating System 2 (ROS 2) is the next generation of the Robot Operating System, designed for production environments. It provides a flexible framework for writing robot software and is widely used in both academic and industrial robotics applications.\\n\\n## Key Concepts\\n\\nROS 2 is built around several core concepts that enable distributed computation and communication between robot components:\\n\\n- **Nodes**: Individual components of a ROS system that perform computation\\n- **Topics**: Named buses over which nodes exchange messages\\n- **Services**: Synchronous request/response communication between nodes\\n- **Actions**: Asynchronous request/response communication with feedback\\n- **Parameters**: Configuration values that can be changed at runtime\\n\\n## Why ROS 2?\\n\\nROS 2 addresses several limitations of the original ROS and introduces improvements for production use:\\n\\n- **Real-Time Support**: Better support for systems requiring deterministic timing\\n- **Multi-Robot Systems**: Improved support for multiple robots working together\\n- **Cross-Platform Support**: Works on Linux, Windows, and macOS\\n- **Security**: Built-in security features for enterprise environments\\n- **ROS 1 Compatibility**: Tools for migrating existing ROS 1 systems\\n\\nThese fundamentals form the basis for all the modules in our course. Understanding these concepts is crucial for building complex robotic applications."},{"id":"welcome-to-blog","metadata":{"permalink":"/blog/welcome-to-blog","editUrl":"https://github.com/panaversity/physical-ai-humanoid-robotics/tree/main/blog/welcome.md","source":"@site/blog/welcome.md","title":"Welcome to Our Robotics Blog","description":"Welcome to the official blog for the Physical AI & Humanoid Robotics textbook. This blog will feature updates, insights, and additional content related to the course.","date":"2025-12-06T21:29:37.000Z","formattedDate":"December 6, 2025","tags":[{"label":"robotics","permalink":"/blog/tags/robotics"},{"label":"ai","permalink":"/blog/tags/ai"},{"label":"humanoid","permalink":"/blog/tags/humanoid"}],"readingTime":0.185,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"welcome-to-blog","title":"Welcome to Our Robotics Blog","tags":["robotics","ai","humanoid"]},"prevItem":{"title":"ROS 2 Fundamentals Explained","permalink":"/blog/ros2-fundamentals"}},"content":"Welcome to the official blog for the Physical AI & Humanoid Robotics textbook. This blog will feature updates, insights, and additional content related to the course.\\n\\nStay tuned for more posts about robotics, AI, and humanoid development!"}]}')}}]);